SELECT errand_order_id FROM errand_order
WHERE errand_order_id > #{lastId}
ORDER BY errand_order_id
LIMIT #{limit}

SELECT FROM errand_order
AND state NOT IN ('DRAFT', 'DELETED')
AND type = #{type}
AND state = #{state}
ORDER BY
reward ASC, errand_order_id ASC reward DESC, errand_order_id DESC create_time ASC, errand_order_id ASC create_time DESC, errand_order_id DESC
LIMIT #{offset}, #{limit}

