SELECT lock_seq
FROM errand_order
WHERE errand_order_id = #{orderId}

mapper.update:
UPDATE errand_order
SET state      = 'CONFIRMED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND taker_id = #{takerId}
  AND state = 'LOCKED'

UPDATE errand_order
SET state      = 'PICKED_UP',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND taker_id = #{takerId}
  AND state = 'CONFIRMED'

UPDATE errand_order
SET state      = 'DELIVERED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND taker_id = #{takerId}
  AND state = 'PICKED_UP'

UPDATE errand_order
SET state      = 'COMPLETED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND publisher_id = #{publisherId}
  AND state = 'DELIVERED'

UPDATE errand_order
SET state      = 'CANCELLED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND publisher_id = #{publisherId}
  AND state IN ('PENDING_PAYMENT', 'PUBLISHED', 'LOCKED', 'CONFIRMED')

UPDATE errand_order
SET event_seq   = event_seq + 1
WHERE errand_order_id = #{orderId}

mapper.select:
SELECT event_seq
FROM errand_order
WHERE errand_order_id = #{orderId}

mapper.update:
UPDATE errand_order
SET state      = 'PENDING_PAYMENT',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND publisher_id = #{publisherId}
  AND state = 'DRAFT'

UPDATE errand_order
SET state      = 'DELETED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND publisher_id = #{publisherId}
  AND state = 'DRAFT'

mapper.select:
SELECT errand_order_id
FROM errand_order
WHERE state = 'PENDING_PAYMENT'
  AND update_time <= #{before}
LIMIT #{limit}

SELECT errand_order_id
FROM errand_order
WHERE state = 'DELIVERED'
  AND update_time <= #{before}
LIMIT #{limit}

