WHERE publisher_id = #{userId}
  AND state != 'DELETED'

    AND state = #{state}

ORDER BY create_time DESC, errand_order_id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM errand_order
WHERE publisher_id = #{userId}
  AND state != 'DELETED'

    AND state = #{state}

